from taf.cloud.ncir.ncir_connection import NcirConnection


class ncir(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.__connection = None

    @property
    def _connection(self):
        if not self.__connection:
            raise RuntimeError('You need to create connection first. '
                               'Please use connect_to keyword.')
        return self.__connection

    def connect_to(self, address, version='ncir_17a', **version_parameters):
        """
        Create a connection to NCIR instance. This obtains a Keystone token for future use.
        Before using any other keyword you have to create a connection.
        :param str address: network address of NCIR
        :param str version: choose NCIR version. Default 'ncir_17a', available: 'ncir_17a'
        :param **version_parameters: parameters specific to NCIR version. E.g. for NCIR 17A
        they are username, password and verify.
        """
        self.__connection = NcirConnection(address, version, **version_parameters)

    def get_host_id_by_name(self, host_name):
        """
        Get host ID by host name.
        :param host_name: host name
        :return: host ID
        """
        return self._connection.get_host_id_by_name(host_name)

    def lock_host(self, host_id):
        """
        Bring an unlocked host out of service. On a controller host switch active host to
        another one before performing this operation. On a compute node succeeds only if
        all currently running instances can be migrated.
        :param host_id: host ID
        """
        self._connection.lock_host(host_id)

    def unlock_host(self, host_id):
        """
        Bring a locked host into service.
        :param host_id: host ID
        """
        self._connection.unlock_host(host_id)

    def force_lock_host(self, host_id):
        """
        Forces an unlocked host to be out of service. A force lock operation on
        a compute host causes an immediate service outage on all hosted virtual
        machines (VM failures) and causes the host to reboot.
        :param host_id: host ID
        """
        self._connection.force_lock_host(host_id)

    def swact_host(self, host_id):
        """
        Switch active host. This forces the other controller to become the active one,
        all active system services on this controller move to standby. Use this first
        if you want to lock the controller host.
        Available for controller hosts only.
        :param host_id: controller host ID
        """
        self._connection.swact_host(host_id)
